"""Writes SORT.md from sort_data.py."""
import sort_data as S
P = {"K": "others' methods only", "O": "our oldest tool only (∘ₖ)", "U": "our newer tools already used"}
H = {"F1": "F1, checked here (settled by later pages)", "F2": "**F2, reworked: opens a lead**", "F3": "**F3, reworked: opens a lead**",
     "F4": "**F4, reworked: opens a lead**", "F5": "F5, reworked: changes the reading only", "answered": "settled by a later page",
     "flag": "flagged: untried with our newer tools", "": "stays closed"}
out = ["# The sort, row by row (DRAFT, Nov 26 2026)", "",
       "Generated by `make_sort.py` from `sort_data.py`. Rows go from the most fundamental layer to the most derived.",
       "About 140 closed leads, grouped into 100 rows as in `closed-leads-revisit/` Part 4 (rows there that bundled",
       "several leads stay bundled). Leads that page already reopened (R1–R6, S1, S2) are not repeated.", ""]
for li, name in enumerate(S.LAYERS):
    rows = [r for r in S.L if r["layer"] == li]
    out += [f"## {name}", "", "| Lead | Folder | Tools used on it before | Our newer tool that bears on it | Here |", "|---|---|---|---|---|"]
    for r in rows:
        out.append(f"| {r['lead']} | {r['folder']} | {P[r['prov']]} | {r['fresh'] or '—'} | {H[r['here']]} |")
    out.append("")
import collections
c = collections.Counter(r["prov"] for r in S.L)
out += ["## Totals", "", f"- Rows: {len(S.L)}.",
        f"- Only other people's methods: {c['K']}. Only our oldest tool: {c['O']}. Our newer tools already used: {c['U']}.",
        f"- Reworked here: {sum(1 for r in S.L if r['here'].startswith('F'))} rows (five reworks). Settled by later pages: "
        f"{sum(1 for r in S.L if r['here']=='answered')}. Flagged: {sum(1 for r in S.L if r['here']=='flag')}."]
open("SORT.md", "w").write("\n".join(out) + "\n")
print("SORT.md written")
